class Solution {
  private int[][] table;
  private int[] log;

  private static int gcd(int a, int b) {
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  private int query(int l, int r) {
    int k = log[r - l + 1];
    return gcd(table[k][l], table[k][r - (1 << k) + 1]);
  }

  private boolean ok(int n, int limit, int maxC) {
    int count = 0, last = -1;
    for (int i = limit; i < n; i++) {
      if (i - limit <= last) continue;
      if (query(i - limit, i) >= 2) {
        count++;
        last = i;
        if (count > maxC) return false;
      }
    }
    return true;
  }

  public int minStable(int[] nums, int maxC) {
    int n = nums.length;
    log = new int[n + 2];
    for (int i = 2; i <= n + 1; i++) log[i] = log[i / 2] + 1;
    table = new int[log[n] + 1][];
    table[0] = nums.clone();
    for (int k = 1; k < table.length; k++) {
      table[k] = new int[n];
      for (int i = 0; i + (1 << k) <= n; i++)
        table[k][i] = gcd(table[k - 1][i], table[k - 1][i + (1 << (k - 1))]);
    }
    int lo = 0, hi = n;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (ok(n, mid, maxC)) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }
}
